args.sql:
SELECT "TxnPointer", "Threat_handle_rate", "AuthLevel"
FROM connection_security, transactions, buyers
WHERE "TxnPointer" = "EventCode" AND "AcqLink" IN (SELECT "AcqCode" FROM buyers);
